'use strict';

function partitionAssetDirectives(source) {
  if (typeof source !== 'string') {
    throw new TypeError('source must be a string');
  }

  const pattern = /^[\t ]*#asset[\t ]+(?:"[^"\r\n]+"|'[^'\r\n]+')/gm;
  const parts = [];
  let cursor = 0;
  let match;

  while ((match = pattern.exec(source)) !== null) {
    if (match.index > cursor) {
      parts.push({ type: 'text', value: source.slice(cursor, match.index).trim() });
    }
    parts.push({ type: 'asset', value: match[0].trimStart() });
    cursor = pattern.lastIndex;
  }

  if (cursor < source.length) {
    parts.push({ type: 'text', value: source.slice(cursor).trim() });
  }

  return parts;
}

module.exports = { partitionAssetDirectives };

