'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['partitionAssetDirectives']);
const { partitionAssetDirectives } = api;
assert.strictEqual(typeof partitionAssetDirectives, 'function');

assert.deepStrictEqual(partitionAssetDirectives(''), []);
assert.deepStrictEqual(partitionAssetDirectives('plain text\n'), [
  { type: 'text', value: 'plain text\n' }
]);
assert.deepStrictEqual(partitionAssetDirectives('#asset "one.png"'), [
  { type: 'asset', value: '#asset "one.png"' }
]);
assert.deepStrictEqual(partitionAssetDirectives("#asset 'a\"b.png'"), [
  { type: 'asset', value: "#asset 'a\"b.png'" }
]);
assert.deepStrictEqual(partitionAssetDirectives('#asset "a\'b.png"'), [
  { type: 'asset', value: '#asset "a\'b.png"' }
]);

const source = 'head\r\n \t#asset "img/a b.png"tail\n\t#asset \'x.png\'\r\n  // #asset "ignored.png"\n#asset ""\n#asset "unterminated\nend';
const snapshot = source;
assert.deepStrictEqual(partitionAssetDirectives(source), [
  { type: 'text', value: 'head\r\n' },
  { type: 'asset', value: '#asset "img/a b.png"' },
  { type: 'text', value: 'tail\n' },
  { type: 'asset', value: "#asset 'x.png'" },
  { type: 'text', value: '\r\n  // #asset "ignored.png"\n#asset ""\n#asset "unterminated\nend' }
]);
assert.strictEqual(source, snapshot);

assert.deepStrictEqual(partitionAssetDirectives('x #asset "no.png"\n\v#asset "also-no.png"'), [
  { type: 'text', value: 'x #asset "no.png"\n\v#asset "also-no.png"' }
]);
assert.deepStrictEqual(partitionAssetDirectives('  #asset "p"   remainder'), [
  { type: 'asset', value: '#asset "p"' },
  { type: 'text', value: '   remainder' }
]);
assert.deepStrictEqual(partitionAssetDirectives('   '), [
  { type: 'text', value: '   ' }
]);

for (const invalid of [null, undefined, 1, true, {}, [], new String('x')]) {
  assert.throws(() => partitionAssetDirectives(invalid), TypeError);
}

